  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle ;', 'prophylaxie des crises d''angor d''effort.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'asthme et broncho‑pneumopathies chroniques obstructives, dans leurs formes sévères ;', 'insuffisance cardiaque non contrôlée par le traitement ;', 'choc cardiogénique ;', 'blocs auriculo-ventriculaires du second et troisième degré non appareillés ;', 'angor de Prinzmetal (dans les formes pures et en monothérapie) ;', 'maladie du sinus (y compris bloc sino‑auriculaire) ;', 'bradycardie (', 'phénomène de Raynaud et troubles artériels périphériques dans leurs formes sévères ;', 'phéochromocytome non traité ;', 'hypotension ;', 'antécédent de réaction anaphylactique ;']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Ne jamais interrompre brutalement le traitement chez les angineux : l''arrêt brusque peut entraîner des troubles du rythme graves, un infarctus du myocarde ou une mort subite.', 'Précautions d''emploi', 'Arrêt du traitement', 'Le traitement ne doit pas être interrompu brutalement, en particulier chez les patients présentant une cardiopathie ischémique.', 'La posologie doit être diminuée progressivement, c''est‑à‑dire sur une à deux semaines, en commençant en même temps, si nécessaire, le traitement substitutif, pour éviter une aggravation de l''angor.', 'Asthme et broncho‑pneumopathies chroniques obstructives', 'Les bêta‑bloquants ne peuvent être administrés qu''aux patients présentant des formes légères de ces pathologies, en choisissant un bêta‑bloquant sélectif à faible dose initiale.', 'Il est recommandé d''effectuer des tests de la fonction pulmonaire avant de commencer le traitement.', 'Un bronchodilatateur bêta-2-agoniste peut être utilisé si une crise d''asthme survient pendant le traitement.', 'Insuffisance cardiaque', 'Chez l''insuffisant cardiaque contrôlé par le traitement et en cas de nécessité, le bétaxolol sera administré à très faibles doses progressivement croissantes et sous surveillance médicale stricte.']);
