  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (³ 1/10).', 'Fréquent (³ 1/100 à Peu fréquent (³ 1/1000 à Rare (³1/10 000 à Très rare (Fréquence indéterminée (ne peut être estimée sur la base des données disponibles).', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Chez l''insuffisant cardiaque contrôlé par le traitement et en cas de nécessité, le bétaxolol sera administré à très faibles doses progressivement croissantes et sous surveillance médicale stricte.']);

  -- propranolol (CIS 65135519)
