  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients listés dans la rubrique 6.1.', 'Insuffisance cardiaque non contrôlée par le traitement.', 'Maladie du sinus /bloc sino-auriculaire.', 'Antécédents de bronchospasme ou d’asthme bronchique, bronchopneumopathie chronique obstructive.', 'Acidose métabolique.', 'Blocs auriculoventriculaires des second et troisième degrés.', 'Prédisposition à l''hypoglycémie (comme après un jeûne ou en cas d''anomalie de réponse aux hypoglycémies).', 'Choc cardiogénique.', 'Phéochromocytome non traité.', 'Bradycardie sévère.', 'Hypotension artérielle sévère', 'Troubles artériels périphériques sévères']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Propranolol, comme pour les autres bêtabloquants :', 'bien que contre-indiqué en cas d''insuffisance cardiaque non contrôlée (voir rubrique 4.3), il peut être utilisé chez les patients dont les signes d''insuffisance cardiaque ont été contrôlés.', 'La prudence doit être exercée chez les patients dont la réserve cardiaque est diminuée ;', 'Cela peut entraîner une hypotension sévère, une bradycardie et une insuffisance cardiaque.', 'Ni le bétabloquant, ni l’inhibiteur des canaux calciques ne doit être administré par voie intraveineuse dans les 48 heures suivant l''arrêt de l''autre.', 'bien que contre-indiqué dans les troubles circulatoires artériels périphériques sévères (voir rubrique 4.3), peut également aggraver les troubles circulatoires artériels périphériques moins sévères ;', 'en raison de son effet négatif sur le temps de conduction, il faut faire preuve de prudence s''il est administré à des patients atteints d''un bloc auriculoventriculaire de premier degré ;', 'peut masquer/modifier les signes annonciateurs d’une hypoglycémie (en particulier, la tachycardie).', 'Des hypoglycémies sévères associées à la prise de propranolol ont rarement conduit à des crises convulsives et/ou un coma.', 'La prudence est recommandée chez les patients diabétiques qui reçoivent un traitement hypoglycémiant concomitant.', 'Le propranolol peut prolonger la réponse hypoglycémique à l’insuline (voir rubrique 4.3) ;', 'peut masquer les signes d’une thyrotoxicose ;']);
